  ('red-sea-egypt', '04A', 'Red Sea', 'Egypt', '*If it''s warm-water wrecks and open-blue sharks a short', 'live', 'verified', 'oceanAerial', 'The Red Sea', '{"liveaboard","diveglobal","ocean","culture"}', '{}', '{"comfort","premier"}', null, 'anchor', '{"key_facts":["Year-round dive sea; prime windows Mar-May and Sep-Nov (liveaboard.com)","Offshore shark reefs (Brothers/Daedalus/Elphinstone) peak Jun-Nov","SS Thistlegorm + Abu Nuhas (5 wrecks) + Salem Express = dense northern wreck field","Fleet: Aggressor (x3), Emperor (x3), Master (Blue Horizon/Blue Melody), Explorer Ventures - TWW holds Aggressor + Explorer reseller lines","Red Sea dive coast outside every carve-out; FCDO concurs); chambers at Sharm/Hurghada/Marsa Shagra/Hamata (DECO 24h) - verified 2026-08-09"],"safety":{"emergency":"122 police / 123 ambulance (verify)","hospital":"coastal hospitals at Sharm el-Sheikh, Hurghada, Marsa Alam (verify)","hyperbaric":"Sharm el-Sheikh Hyperbaric Medical Center (DAN Egypt); HyperMed Hurghada (by the airport); Baro Medical Marsa Shagra (~20km N of Marsa Alam); DECO International Hamata (24h, ~135km S of Marsa Alam) - confirm itinerary chamber + dates via DAN/operator (source: emperordivers.com + deco-international.com, 2026-08-09)","no_fly_after_diving":"18-24h (DAN)","malaria":"none in the Red Sea resort/dive corridor (verify)","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/egypt","read":"2026-09-01T16:19:18Z","page_updated":"2026-08-04T11:10:57+01:00","source_country":"egypt","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"Sinai Peninsula","lvl":4,"except":["Sharm el-Sheikh, arriving by air"]},{"name":"The Western Desert","lvl":4},{"name":"The Libya and Sudan border areas","lvl":4}]},"timing":{"peak":"Mar-May & Sep-Nov (calm, warm, 30m+ viz)","shoulder":"Jun-Aug summer (30C, strongest offshore sharks, some plankton; liveaboards favour calm south)","green":"Dec-Feb (21-23C, windier offshore, fewer crowds; south stays viable)","booking_lead":"peak shark-season/marquee wreck weeks ~3-9 months for preferred vessels; shoulder nearer term; confirm per-vessel with operator","off_season_specials":"winter southern routes at lower demand; wreck routes hold year-round","event_peaks":"Jun-Nov offshore shark season is the sea''s demand spike","fire_date":"shark-season southern routes fire Mar-Apr; wreck/shoulder fire Dec-Jan"},"jewels":[{"name":"SS Thistlegorm","status":"live","tier":"premier","hook":"WWII wreck, the sea''s signature dive","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/egypt","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"WWII wreck, the sea''s signature dive","when":"Mar-May & Sep-Nov","commission":"fleet-direct (Aggressor/Explorer reseller line)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","liveaboard"],"shelf_fit":{"culture":"destination","diveglobal":"evidenced","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The Brothers (Big & Small)","status":"live","tier":"premier","hook":"thresher and oceanic sharks, early-morning threshers","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/season-calendar/best-time-to-dive-in-the-red-sea","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"thresher and oceanic sharks, early-morning threshers","when":"Mar-May & Sep-Nov","commission":"fleet-direct","wells":["stay"],"wells_basis":"full pass 2026-10-05, additive — bookable_category","si_all":["liveaboard"],"shelf_fit":{"culture":"destination","diveglobal":"destination","liv