","blurb":"the Sinai marine reserve","when":"Mar-May & Sep-Nov","commission":"fleet-direct / day-op","wells":["move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["liveaboard","ocean"],"shelf_fit":{"culture":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"evidenced"},"commission_lane":["operator","fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Straits of Tiran (Jackson/Woodhouse/Thomas/Gordon)","status":"live","tier":"comfort","hook":"four northern reefs","bookable_category":"liveaboard/day-boat","source":"https://www.liveaboard.com/diving/egypt","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"four northern reefs","when":"Mar-May & Sep-Nov","commission":"fleet-direct / day-op","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["liveaboard","ocean"],"shelf_fit":{"culture":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"evidenced"},"commission_lane":["operator","fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Abu Nuhas (five wrecks)","status":"live","tier":"comfort","hook":"the northern wreck cluster","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/egypt","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"the northern wreck cluster","when":"Mar-May & Sep-Nov","commission":"fleet-direct","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["diveglobal","liveaboard"],"shelf_fit":{"culture":"destination","diveglobal":"evidenced","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Salem Express","status":"live","tier":"comfort","hook":"passenger-ferry wreck (sank 1991)","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/egypt","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"passenger-ferry wreck (sank 1991)","when":"Mar-May & Sep-Nov","commission":"fleet-direct","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["diveglobal","liveaboard"],"shelf_fit":{"culture":"destination","diveglobal":"evidenced","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Fury Shoals","status":"live","tier":"premier","hook":"southern reef complex from Marsa Alam","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/egypt","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"southern reef complex from Marsa Alam","when":"Mar-May & Sep-Nov","commission":"fleet-direct","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["liveaboard"],"shelf_fit":{"culture":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"St John''s reefs","status":"live","tier":"premier","hook":"290+ km2 of far-southern reef near the Sudan border","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/egypt","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"290+ km2 of far-southern reef near the Sudan border","when":"Mar-May & Sep-Nov","commission":"fleet-direct","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["liveaboard"],"shelf_fit":{"culture":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Northern Wreck & Reef route","status":"live","tier":"premier","hook":"Thistlegorm + Abu Nuhas + Ras Mohammed + Tiran, year-round","bookable_category":"liveaboard week","source":"https://www.liveaboard.com/diving/egypt","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Thistlegorm + Abu Nuhas + Ras Mohammed + Tiran, year-round","when":"Mar-May & Sep-Nov","commission":"fleet-direct (Aggressor/Explorer)","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["diveglobal","liveaboard"],"shelf_fit":{"culture":"destination","diveglobal":"evidenced","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Southern BDE offshore shark route","status":"live","tier":"premier","hook":"Brothers-Daedalus-Elphinstone, Jun-Nov","bookable_category":"liveaboard week","source":"https://www.liveaboard.com/diving/season-calendar/best-time-to-dive-in-the-red-sea","timing":"Mar-May & Sep-Nov","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Brothers-Daedalus-Elphinstone, Jun-Nov","when":"Mar-May & Sep-Nov","commission":"fleet-direct (Aggressor/Explorer)","wells":["stay"],"wells_basis":"full pass 2026-10-05, additive — bookable_category","si_all":["liveaboard"],"shelf_fit":{"culture":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What is the current advisory for the Egyptian Red Sea, and how do I dive it responsibly?","a":"the Red Sea coast sits outside every carve-out, so Hurghada and the northern Red Sea coast carry no sub-zone restriction. The UK FCDO draws the same interior zones in its own words and names no Red Sea resort; Carry DAN membership plus separate dive-accident insurance and observe an 18-24 hour no-fly window after diving.","source":"https://www.gov.uk/foreign-travel-advice/egypt","si_tag":"safety"},{"q":"Is there a recompression chamber, and how remote is care?","a":"The Red Sea coast runs a dense chamber network. Northern routes are covered by the Hyperbaric Medical Center in Sharm el-Sheikh (DAN Egypt) and HyperMed in Hurghada (next to the airport); southern routes by Baro Medical in Marsa Shagra (about 20 km north of Marsa Alam) and the DECO International chamber in Hamata (a 24-hour recompression and medical-emergency facility about 135 km south of Marsa Alam). Confirm the chamber covering your itinerary and its readiness on your dates via the operator or DAN. Offshore reefs are hours from port, so insurance and a conservative profile matter most there.","source":"emperordivers.com/recompression-dcs-and-diving-safety + deco-international.com (accessed 2026-08-09)","si_tag":"safety","accessed":"2026-08-09"},{"q":"When is the best time to dive the Red Sea?","a":"March-May and September-November are the optimal windows - calm seas, warm water and 30 m+ visibility. Summer (June-August) pushes water to 30C with strong offshore shark action but occasional plankton; winter (December-February) drops to 21-23C and can be windy offshore.","source":"liveaboard.com/diving/season-calendar/best-time-to-dive-in-the-red-sea","si_tag":"planning"},{"q":"When can I see oceanic whitetips, hammerheads and threshers?","a":"June-November is the offshore shark window: oceanic whitetips, grey reef and scalloped hammerheads around Daedalus and Elphinstone, with The Brothers known for thresher sharks in the early morning.","source":"liveaboard.com/diving/season-calendar/best-time-to-dive-in-the-red-sea","si_tag":"liveaboard"},{"q":"North route or south route - which liveaboard week?","a":"North runs the wrecks and reefs - SS Thistlegorm, Abu Nuhas, Ras Mohammed and the Straits of Tiran (Jackson, Woodhouse, Thomas, Gordon). South runs the offshore shark reefs (Brothers, Daedalus, Elphinstone) and the remote Fury Shoals and St John''s near the Sudan border; liveaboards favour the calm southern conditions in summer.","source":"liveaboard.com/diving/egypt","si_tag":"liveaboard"},{"q":"What certification and conditions should I plan for?","a":"The offshore reefs (Brothers, Daedalus, Elphinstone) are current-swept blue-water sites suited to experienced divers; the northern wrecks and Tiran reefs suit a wider range with a guide. Nitrox is standard on most liveaboards for the repetitive multi-day profile. Dive within your certification and the operator briefing.","source":"liveaboard.com/diving/egypt","si_tag":"liveaboard"},{"q":"How far ahead do Red Sea liveaboards book?","a":"Peak shark-season southern weeks (June-November) and the marquee wreck routes fill earliest; hold a berth roughly 3-9 months out for peak windows and preferred vessels, with shoulder weeks bookable nearer term. Confirm current per-vessel lead times with the operator.","source":"liveaboard.com/diving/egypt","si_tag":"planning"}],"seo":{"meta_title":"Red Sea Liveaboard Diving, Egypt: Wrecks, Sharks & Season","meta_description":"The Egyptian Red Sea liveaboard sea - SS Thistlegorm and the northern wrecks, the Brothers-Daedalus-Elphinstone shark reefs, season, operators and safety.","slug":"red-sea-egypt","primary_keyword":"Red Sea liveaboard diving","long_tail":["SS Thistlegorm wreck dive","Brothers Daedalus Elphinstone sharks","Red Sea dive season","Egypt liveaboard operators","Ras Mohammed Straits of Tiran"],"search_language":"ar-EG (restated, not machine-translated)","local_keywords":["غوص البحر الأحمر","حطام ثيسلغورم","غطس الإخوة دايدلوس"],"hreflang":["en","ar-EG"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-09","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-09","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/egypt","read":"2026-08-20T14:48:39Z","source_updated":"2026-08-04T11:10:57+01:00"}]}},"booking":{"codes":[],"advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-08-09","hits":4,"misses":18,"disregarded":3,"note":"Liveaboard-diving destination; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"},{"si":"culture","name":"culture","status":"future"}],"ultra":[{"name":"Private full-boat liveaboard charter (Aggressor/Master/Emperor) + Cairo-Nile add-on","why_ultra":"the Red Sea ultra pull is a private charter of a premium vessel for a family/club, paired with a Nile land week","earning":"held fleet reseller line for Aggressor/Explorer; verify Master/Emperor charter terms","virtuoso_value_add":"verify - not documented","mor":"commission-on-net where the fleet pays; no net-rate resale markup","source":"handoff/LIVEABOARD-OPERATOR-GRID-2026-08-09.md"}],"source_verified":"2026-08-09","hero":{"query":"Red Sea, Egypt"},"geo":{"lat":25.5,"lng":34.8},"orbit":[],"orbit_country":["aswan-egypt","cairo-egypt","luxor-egypt"]}'::jsonb, 15)
