  ('wadi-rum-jordan', '04A', 'Wadi Rum', 'Jordan', 'The Valley of the Moon', 'live', 'verified', 'desertDunes', 'Jordan & the Levant', '{"adventure","ultra","culture"}', '{}', '{"essential","comfort","premier","ultra"}', null, 'anchor', '{"key_facts":["The Valley of the Moon - a 74,000-ha sandstone-and-granite desert; UNESCO World Heritage since 2011 (a MIXED cultural + natural site)","Bedouin country - classic goat-hair tents through to luxury bubble/dome camps under some of the clearest night skies on Earth","Jeep safaris, camel treks, rock climbing, ancient rock art, and film-set fame (Lawrence of Arabia country; a favorite desert-planet backdrop)","Wadi Rum entry is included in the Jordan Pass; an hour south of Petra - the two make one trip","Best season March-April & October-November; summer days ~40C, winter nights can drop below freezing"],"safety":{"emergency":"911 (unified - police / ambulance / civil defense); Tourist Police +962 79 550 5755","hospital":"Aqaba + Amman for major referral; carry travel-medical + evac insurance","activity_note":"Wadi Rum is in the deep south, far from them. Extreme day heat / cold nights; go with a registered Bedouin camp/guide; water + sun cover; guided rock climbing only.","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/jordan","read":"2026-08-31T18:23:11Z","page_updated":"2026-08-25T16:36:13+01:00","source_country":"jordan","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The Syria and Iraq border areas","lvl":4},{"name":"Designated refugee camps","lvl":4},{"name":"Rusayfah","lvl":4},{"name":"The Baqa''a area of Ayn Basha","lvl":4},{"name":"Mansheyat al Ghayyath and Ruwayshid","lvl":4,"note":"Cross-border violence, terrorism and crime."},{"name":"Zarqa City","lvl":3,"note":"Terrorism and crime."}]},"timing":{"peak":"Mar-Apr & Oct-Nov (warm days, cool nights)","shoulder":"Mar + Nov","green":"Jun-Aug (~40C days, dawn/dusk touring) + Dec-Feb (freezing nights, quiet)","booking_lead":"luxury bubble camps capacity-tight in peak - book well ahead","off_season_specials":"summer + winter value; pair with Petra + Dead Sea + Amman","event_peaks":"spring + autumn peak; clear-sky stargazing year-round","fire_date":"sell spring/autumn desert nights 2-4 mo out; lead EN + GCC + DE; stargazing + luxury-camp angles"},"jewels":[{"name":"A night in a glass bubble under the Milky Way","status":"live","tier":"premier","price_band":"book ahead","timing":"Mar-Nov","draw_rank":1,"hook":"luxury dome camps with clear-sky stargazing — Wadi Rum''s signature high-margin stay","si":"ultra","blurb":"luxury dome camps with clear-sky stargazing — Wadi Rum''s signature high-margin stay","when":"Mar-Nov","commission":"DMC/consortia 10-16%","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["adventure","expedition","ultra"],"shelf_fit":{"adventure":"evidenced","culture":"destination","expedition":"evidenced","ultra":"primary"},"commission_pct_low":10,"commission_pct_high":16,"commission_lane":["DMC","consortia"],"commission_embedded":false,"commission_basis":"band+lane","si_basis":"the dossier''s own SI block filed this jewel under a heading resolving to ''adventure'' via ruled RULES. Not a keyword match on the jewel text."},{"name":"A dawn 4x4 safari across the red sand","status":"live","tier":"essential","price_band":"within the stay","timing":"Mar-Apr & Oct-Nov","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"dunes, arches, canyons, and rock art with a Bedouin driver-guide","si":"adventure","blurb":"dunes, arches, canyons, and rock art with a Bedouin driver-guide","when":"Mar-Apr & Oct-Nov","commission":"DMC 10-15%","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["adventure","culture"],"shelf_fit":{"adventure":"primary","cultu