rum-jordan","primary_keyword":"Wadi Rum Jordan","long_tail":["Wadi Rum bubble camp","Wadi Rum jeep safari","is Wadi Rum safe","Wadi Rum stargazing","best time to visit Wadi Rum","Wadi Rum luxury camp"],"search_language":"en","local_keywords":["Wadi Rum","Valley of the Moon","Bedouin","Disi","Rum village"],"hreflang":["en","ar","de"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-03","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-03","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/jordan","read":"2026-08-20T14:48:55Z","source_updated":"2026-07-22T13:47:55+01:00"}]}},"booking":{"codes":["reconsider-travel","regional-tensions","terrorism"],"book_suppressed":false,"note":"Disclose PROMINENTLY; heightened-consent booking. Operators run desert camps + tours through 2026. Re-verify each cycle (may revert to).","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-08-03","hits":3,"misses":18,"disregarded":3,"note":"Desert adventure + ultra: adventure (jeep/camel/climb) + ultra (bubble/dome camps) + culture (Bedouin/UNESCO mixed) live; deepdive (Bedouin ethnography) future. glamping SI not live - luxury camps ride on ultra + adventure. sub_region ''Jordan & Petra'' PROPOSED."},"sis_present":[{"si":"globaladv","name":"adventure","status":"live","note":"jeep safari, camel trek, rock climbing/scrambling, guided stargazing"},{"si":"ultra","name":"ultra","status":"live","note":"luxury bubble/dome desert camps under clear skies - high-margin signature stay"},{"si":"culture","name":"culture","status":"live","note":"Be