  ('kibale-forest-uganda', '05A', 'Kibale Forest National Park', 'Uganda', 'The primate capital of the world', 'live', 'verified', 'mountainValley', 'Uganda — Kibale Forest', '{"adventure","deepdive","ultra","culture"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["CONTENT-ONLY, no Book path, no waiver. DYNAMIC - re-verify each cycle, flip to live when it clears. Redirect chimp demand to Rwanda''s Nyungwe","The primate capital of the world: up to ~1,500 chimpanzees and 13 primate species in a lush tropical rainforest - the richest primate community in East Africa","The chimp trek is the draw (globaladv-primary) - $250 permit (foreign non-resident), plus the full-day Habituation Experience ~$300; safari (big game) is a documented MISS - a forest, not a savanna","Bigodi wetland (Magombe) community birding walk on the forest edge (200+ birds + primates) - a model of community tourism (all latent while held)","Yellow fever MANDATORY for entry (all >=1yr, checked at Entebbe); eVisa (no visa-on-arrival); malaria in all regions incl. Kibale forest (prophylaxis); chimp-trek rules ~8m/mask/1hr/ranger/no-trek-if-ill - all latent while held","Anchors the Uganda cluster with bwindi/queen-elizabeth/murchison-falls"],"safety":{"emergency":"999 / 112","hospital":"Remote - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Fort Portal/Kampala (all latent while held)","malaria":"present in all regions incl. Kibale forest - prophylaxis (latent while held)","yellow_fever":"MANDATORY for entry (all >=1yr, checked at Entebbe, >=10 days before)","ebola":"Sudan virus outbreak - PHEIC declared 2026-05-17 - the dominant, disqualifying hazard","activity_note":"HEALTH-SPINE DOMINANT: Ebola outbreak is the hazard. FCDO BASIS (gov.uk/foreign-travel-advice/uganda, read 2026-08-20): health screening on arrival and departure; Ugandan border with the DRC closed from 27 May per the National Task Force; the UK Returning Workers Scheme activated due to the outbreak. NOTE THE FCDO ADVISES AGAINST NO TRAVEL TO UGANDA - posture 1 - so any book-suppression here is OUR health judgement, not an advisory one, and is DAVID''S CALL - CONTENT-ONLY, Book suppressed, no waiver, redirect to Rwanda''s Nyungwe. DYNAMIC - re-verify each cycle. Chimp-trek + malaria hazards secondary and moot while held. When reopened: chimp-trek rules ~8m/mask/1hr/ranger/no-trek-if-ill; warm humid forest walk (moderate)","booking_hold":false,"fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/uganda","read":"2026-09-04T12:02:58Z","page_updated":"2026-09-02T16:45:31+01:00","source_country":"uganda","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed","posture_basis":"alert_status empty; quoted sentences name another country","posture_corrected":"2026-08-23 - was AREA-RESTRICTED, derived from prose about a neighbour"},"posture":"book-freely"},"timing":{"latent_peak":"Jun-Sep + Dec-Feb (drier, firmer forest trails; permits scarce) - IF cleared","latent_green":"Mar-May + Oct-Nov (rains, muddier; chimps lower/closer with fruiting)","latent_booking_lead":"permits + lodges 2-4 mo peak - NOT applicable while held","reverify_trigger":"check Uganda''s advisory EVERY publish cycle - DYNAMIC health advisory; flip to live the moment it drops below"},"jewels":[{"name":"Chimpanzee trekking in the primate capital","status":"held","tier":"premier","price_band":"HELD ($250 permit latent)","timing":"HELD; latent Jun-Sep + Dec-Feb","draw_rank":null,"hook":"the finest chimp trek in Africa — up to 1,500 chimps in a lush rainforest","si":"adventure","blurb":"the finest chimp trek in Africa — up to 1,500 chimps in a lush rainforest","when":"HELD; latent Jun-Sep + Dec-Feb","commission":"none (advisory hold)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","culture":"destination","deepdive":"destination","ultra":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The full-day Chimpanzee Habituation Experience","status":"held","tier":"premier","price_band":"HELD (~$300 latent)","timing":"HELD","draw_rank":null,"hook":"shadow the researchers from dawn nest to dusk nest with a semi-habituated community","si":"adventure","blurb":"shadow the researchers from dawn nest to dusk nest with a semi-habituated community","when":"HELD","commission":"none (advisory hold)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","culture":"destination","deepdive":"destination","ultra":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"13 primates + a birding forest","status":"held","tier":"premier","price_band":"HELD - no book path","timing":"HELD","draw_rank":null,"hook":"the richest primate community in East Africa — 13 species plus 370+ birds; a specialist primate/birding week. STATUS: HELD","si":"deepdive","blurb":"the richest primate community in East Africa — 13 species plus 370+ birds; a specialist primate/birding week. STATUS: HELD","when":"HELD","commission":"none (advisory hold)","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["deepdive"],"shelf_fit":{"adventure":"destination","culture":"destination","deepdive":"primary","ultra":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The Bigodi wetland community walk","status":"held","tier":"essential","price_band":"HELD - no book path","timing":"HELD","draw_rank":null,"hook":"the community-run Bigodi Swamp walk on the forest edge — 200+ birds, more primates and a model of community tourism. STATUS: HELD","si":"culture","blurb":"the community-run Bigodi Swamp walk on the forest edge — 200+ birds, more primates and a model of community tourism. STATUS: HELD","when":"HELD","commission":"none (advisory hold)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"adventure":"destination","culture":"primary","deepdive":"destination","ultra":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A crater-and-forest lodge honeymoon (held)","status":"held","tier":"comfort","price_band":"HELD - no book path","timing":"HELD","draw_rank":null,"hook":"Kyaninga Lodge above its crater lake, Ndali Lodge, Primate Lodge in the forest — the ultra way to do the chimps","si":"ultra","blurb":"Kyaninga Lodge above its crater lake, Ndali Lodge, Primate Lodge in the forest — the ultra way to do the chimps","when":"HELD","commission":"none (advisory hold)","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["ultra"],"shelf_fit":{"adventure":"destination","culture":"destination","deepdive":"destination","ultra":"primary"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Where can I trek chimps instead, right now?","a":"Rwanda - Nyungwe Forest. We route all chimp demand there. **FCDO travel advice for Uganda:** the FCDO names no advisory against travel to Uganda. *https://www.gov.uk/foreign-travel-advice/uganda — page updated 2026-07-27.*","source":"travelweekly.com","si_tag":"safety"},{"q":"Will this clear - should I wait for Kibale?","a":"Possibly - this is a health-driven, dynamic advisory (an outbreak, not conflict), so it can be lifted when the outbreak is contained. For a firm 2026 chimp trek, book Nyungwe now.","source":"travelweekly.com","si_tag":"safety"},{"q":"What would Kibale offer when it reopens?","a":"The primate capital of the world - up to 1,500 chimps and 13 primate species, the $250 chimp trek (and the full-day ~$300 Habituation Experience), plus the Bigodi wetland birding walk. All held until the advisory lifts.","source":"gorillatrackers.com","si_tag":"globaladv"},{"q":"Is Kibale a safari (big-game) destination?","a":"No - it is a rainforest of primates, not a savanna, so big-game safari is a documented miss; the draw is the chimp and primate trek (a Global Adventures product), exactly like Rwanda''s Nyungwe. For Big game, we route to Kenya, Tanzania or Akagera.","source":"gorillatrackers.com","si_tag":"globaladv"},{"q":"What are the non-Ebola health requirements for Uganda?","a":"Yellow fever is mandatory for entry (all travelers >=1 yr, checked at Entebbe, vaccinate >=10 days before); malaria prophylaxis is essential (all regions); carry AMREF Flying Doctors + insurance.","source":"cdc.gov","si_tag":"safety"}],"seo":{"meta_description":"What it is, why it''s held, and where to trek chimps instead (Rwanda''s Nyungwe Forest).","slug":"kibale-forest-uganda","primary_keyword":"Kibale Forest chimpanzee trekking","long_tail":["Kibale chimpanzee permit cost 2026","chimpanzee habituation experience Uganda","Kibale primate capital","Bigodi wetland walk","is Uganda safe Ebola","Kibale vs Nyungwe"],"search_language":"en","local_keywords":["Kibale","chimpanzee","Bigodi","Magombe","Kanyanchu","red colobus"],"hreflang":["en"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-01","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-01","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/uganda","read":"2026-08-20T14:48:47Z","source_updated":"2026-07-27T15:00:28+01:00"}]}},"booking":{"codes":["do-not-travel","ebola-sudan-virus-pheic","health-outbreak"],"book_suppressed":true,"waiver":false,"dynamic":true,"note":"CONTENT-ONLY, Book button suppressed, no waiver. DYNAMIC health advisory - re-verify EVERY publish cycle","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-08-01","hits":6,"misses":16,"disregarded":3,"note":"Canonical 25-SI list; per the safari-build rule the chimp trek is globaladv (PRIMARY here) - safari (big game) is a documented MISS on a rainforest; birding/13-primates = deepdive; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"globaladv","name":"adventure","status":"held","note":"chimp trek + full-day Habituation Experience (PRIMARY)"},{"si":"deepdive","name":"deepdive","status":"held","note":"13 primate species / birding"},{"si":"ultra","name":"ultra","status":"held"},{"si":"culture","name":"culture","status":"held","note":"Bigodi wetland community walk"}],"ultra":[{"name":"Kyaninga Lodge / Ndali Lodge (HELD)","why_ultra":"the area''s apex stays - hand-built log-and-crater-lake lodges above the forest; documented for the day the hold lifts, sold by no one today","earning":"none while held","virtuoso_value_add":false,"tier":"ultra","status":"HELD"},{"name":"A private double-chimp + Habituation + Bigodi week (HELD)","why_ultra":"the standard trek + the full-day habituation + the 13 primates + the Bigodi wetland, privately guided - latent","earning":"none while held","virtuoso_value_add":false,"tier":"ultra","status":"HELD"}],"source_verified":"2026-08-01","hero":{"query":"Kibale Forest National Park, Uganda"},"geo":{"lat":0.49,"lng":30.39},"orbit":[],"orbit_country":["bwindi-impenetrable-uganda","murchison-falls-uganda","queen-elizabeth-np-uganda"]}'::jsonb, 8),
  ('laikipia-kenya', '05A', 'Laikipia Plateau', 'Kenya', 'Kenya''s conservancy country', 'live', 'verified', 'lion', 'Kenya — Laikipia Plateau', '{"safari","ultra","adventure","romance","deepdive"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Kenya''s private-conservancy heartland (Ol Pejeta, Lewa, Borana, Loisaba, Solio) - low-density, exclusive; the LAST TWO northern white rhinos on Earth (Najin + Fatu, Ol Pejeta, on-site IVF programme)","Ol Pejeta (90,000 acres) = largest black-rhino population in East Africa + Sweetwaters Chimpanzee Sanctuary (only chimps in Kenya); Lewa (UNESCO 2013) = ~12% of Kenya''s black rhino + largest Grevy''s zebra population","Do-more safari on private land: horseback safaris, walking safaris (armed guide), night drives, lion tracking, mountain biking, camel treks, star beds - all banned in the national parks","best Jul-Oct + Dec-Mar but rewarding year-round - the anchor when migration parks peak-price","Sold via Kenya safari DMCs at a FAVOURABLE 15-22% - IATAN/host-gated, CLIA has NO Africa representation; conservancy/conservation fees non-commissionable pass-through","KES (~129/USD) + M-Pesa but safari quoted USD; eTA required; malaria lower at ~1,800m but present (prophylaxis advised); YF only if arriving from a risk country; AMREF for the on-foot/horse activities"],"safety":{"emergency":"999 / 112 (limited in remote areas); Kenya Red Cross ambulance 1199; AMREF Flying Doctors for bush evac","hospital":"Remote plateau - AMREF Flying Doctors (~$40 pp/30d, air evac) + travel-medical insurance; nearest referral Nanyuki/Nairobi","malaria":"lower at ~1,800m but present - prophylaxis advised (chloroquine-resistant); DEET at dusk","yellow_fever":"compulsory only if arriving from a risk country; CDC recommends for most","activity_note":"Signature on-foot/on-horse/night safaris among dangerous game - armed conservancy guides only, higher-risk than a vehicle, follow instruction. Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/kenya","read":"2026-09-01T16:18:02Z","page_updated":"2026-09-01T12:05:48+01:00","source_country":"kenya","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"Mandera, Wajir and Garissa counties","lvl":4,"note":"The Somalia border counties."},{"name":"Lamu County","lvl":4},{"name":"Tana River","lvl":4},{"name":"Kilifi north of Malindi","lvl":4},{"name":"The northern border areas","lvl":4},{"name":"Eastleigh, Nairobi","lvl":3},{"name":"Kibera, Nairobi","lvl":3}]},"timing":{"peak":"Jul-Oct + Dec-Mar (dry) - best game + activities; conservancy camps busiest but low-density caps keep it quiet","shoulder":"Jun + Nov (good, softer rates)","green":"Apr-May (long rains - lush, quiet, cheapest; plateau still delivers)","booking_lead":"conservancy lodges 4-9 mo (Jul-Oct + Dec-Mar; camps small + capped); shoulder 2-4 mo; green 1-2 mo","off_season_specials":"Apr-May green-season value; the year-round anchor when migration parks peak-price; combine Samburu (Special Five) or the Mara","event_peaks":"Jul-Oct + Christmas/NY + Easter; Lewa Safari Marathon (~Jun, verify) spikes Lewa","fire_date":"conservancy weeks 6-9 mo out; market year-round + green value vs the migration-park price crush; bundle Laikipia (rhino) + Amboseli/Mara to complete the Big Five"},"jewels":[{"name":"The last two northern white rhinos (Ol Pejeta)","status":"live","tier":"premier","price_band":"~$600-2,000/pp/day","timing":"Jul-Oct + Dec-Mar","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"stand beside Najin and Fatu — the last two northern white rhinos on Earth","si":"safari","blurb":"stand beside Najin and Fatu — the last two northern white rhinos on Earth","when":"Jul-Oct + Dec-Mar","commission":"conservancy DMC 15-22%","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''conservancy dmc 15-22%''","si_all":["safari"],"shelf_fit":{"adventure":"destination","deepdive":"destination","romance":"destination","safari":"primary","ultra":"destination"},"commission_pct_low":15,"commission_pct_high":22,"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"A low-density Big-Five conservancy safari","status":"live","tier":"premier","price_band":"~$600-2,500/pp/day","timing":"Jul-Oct + Dec-Mar","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Big Five with a fraction of the vehicles across Ol Pejeta/Lewa/Borana/Loisaba — plus Lewa''s endangered Grevy''s zebra — the exclusive, quiet Kenya","si":"safari","blurb":"Big Five with a fraction of the vehicles across Ol Pejeta/Lewa/Borana/Loisaba — plus Lewa''s endangered Grevy''s zebra — the exclusive, quiet Kenya","when":"Jul-Oct + Dec-Mar","commission":"conservancy DMC 15-22%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["safari"],"shelf_fit":{"adventure":"destination","deepdive":"destination","romance":"destination","safari":"primary","ultra":"destination"},"commission_pct_low":15,"commission_pct_high":22,"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Horseback + walking + night safari","status":"live","tier":"premier","price_band":"~$50-300/pp","timing":"Jul-Oct + Dec-Mar","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"track lion on foot, ride among the zebra, and drive after dark for leopard","si":"adventure","blurb":"track lion on foot, ride among the zebra, and drive after dark for leopard","when":"Jul-Oct + Dec-Mar","commission":"conservancy DMC","wells":["stay","move","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","safari"],"shelf_fit":{"adventure":"primary","deepdive":"destination","romance":"destination","safari":"evidenced","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Rhino conservation + Sweetwaters chimps","status":"future","tier":"essential","price_band":"~$40-200/pp","timing":"Jul-Oct + Dec-Mar","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"behind-the-scenes conservation tours, the northern-white-rhino IVF story, and Kenya''s only chimpanzees at Sweetwaters — a genuine conservation deep-dive","si":"deepdive","blurb":"behind-the-scenes conservation tours, the northern-white-rhino IVF story, and Kenya''s only chimpanzees at Sweetwaters — a genuine conservation deep-dive","when":"Jul-Oct + Dec-Mar","commission":"conservancy/DMC","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["deepdive"],"shelf_fit":{"adventure":"destination","deepdive":"primary","romance":"destination","safari":"destination","ultra":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A conservancy luxury honeymoon (Loisaba / Segera / Borana)","status":"live","tier":"luxury","price_band":"~$800-3,000+/night all-in","timing":"standing; peak 4-9 mo","draw_rank":1,"hook":"Laikipia''s apex camps — Loisaba''s star beds, Segera''s art-filled sanctuary, Borana''s Big-Five ridge — private, exclusive and activity-rich; honeymoon-grade","si":"ultra","blurb":"Laikipia''s apex camps — Loisaba''s star beds, Segera''s art-filled sanctuary, Borana''s Big-Five ridge — private, exclusive and activity-rich; honeymoon-grade","when":"standing; peak 4-9 mo","commission":"consortia/Virtuoso + DMC","wells":["stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["romance","ultra"],"shelf_fit":{"adventure":"destination","deepdive":"destination","romance":"evidenced","safari":"destination","ultra":"primary"},"commission_lane":["DMC","consortia"],"commission_embedded":false,"commission_basis":"lane"},{"name":"A Laikipia conservancy honeymoon","status":"live","tier":"luxury","price_band":"on application","timing":"Jul-Oct + Dec-Mar","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jul-Oct + Dec-Mar","commission":"consortia/host","wells":["stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["romance"],"shelf_fit":{"adventure":"destination","deepdive":"destination","romance":"primary","safari":"destination","ultra":"destination"},"commission_lane":["consortia"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for in Laikipia?","a":"The on-foot and on-horse activities, and remoteness. Laikipia''s draw is walking, horseback and night safaris among dangerous game - inherently higher-risk than a vehicle; go only with the armed conservancy guides and follow instruction. The plateau is remote, so carry AMREF Flying Doctors (~$40 pp/30 days) + travel-medical insurance.","source":"africanmeccasafaris.com","si_tag":"safety"},{"q":"Where do I see rhino - and the last two northern whites?","a":"At Ol Pejeta (the last two northern white rhinos, Najin and Fatu, in a guarded 700-acre enclosure, plus East Africa''s largest black-rhino population) and Lewa (~12% of Kenya''s black rhino, plus Grevy''s zebra) - the best rhino viewing in Kenya, and a genuine conservation story.","source":"expertafrica.com","si_tag":"safari"},{"q":"When is the best time to visit Laikipia?","a":"Jun/Jul-Oct and Dec-Mar (dry) are best, but the high plateau delivers year-round - a strong choice when the migration parks are at their peak-price crush. The green season is lush, quiet and better value.","source":"safaribookings.com","si_tag":"safari"},{"q":"What can I do in Laikipia that I can''t in the national parks?","a":"Because it''s private conservancy land: horseback safaris, walking safaris, night drives, lion tracking, mountain biking, camel treks and star beds - the active, immersive safari the parks don''t allow, with a fraction of the vehicles.","source":"asiliaafrica.com","si_tag":"globaladv"},{"q":"Do I need a visa or yellow-fever certificate for Kenya?","a":"An eTA (Kenya replaced visas with the eTA in 2024 - apply at least 2 weeks ahead). Yellow fever is compulsory only if you arrive from a YF-risk country; CDC recommends the vaccine for most.","source":"cdc.gov","si_tag":"safari"}],"seo":{"meta_title":"Laikipia Safari Guide: Ol Pejeta, the Last Northern White Rhinos, Conservancies & Best Time","meta_description":"Plan a Laikipia safari - Kenya''s private-conservancy heartland: the last two northern white rhinos at Ol Pejeta, East Africa''s biggest black-rhino sanctuary, Lewa''s Grevy''s zebra, Kenya''s only chimps, and low-density safari you can do on foot, horseback or after dark - with real safety, timing and cost.","slug":"laikipia-kenya","primary_keyword":"Laikipia safari","long_tail":["Ol Pejeta northern white rhino","Laikipia conservancies","Lewa Wildlife Conservancy","Sweetwaters chimpanzee sanctuary","horseback safari Kenya","best time Laikipia","is Laikipia safe"],"search_language":"sw","local_keywords":["Laikipia","Ol Pejeta","faru weupe","Lewa","Sweetwaters","safari ya farasi","punda milia wa Grevy"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-31","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-31","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/kenya","read":"2026-08-20T14:53:50Z","source_up